import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on effect size and significance
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for driver selection
        # Use absolute difference in means between groups as effect measure
        mean_y0 = feats.x[feats.y == 0, i].mean()
        mean_y1 = feats.x[feats.y == 1, i].mean()
        effect = abs(mean_y1 - mean_y0)
        effects.append((effect, fid))

    # Sort by effect size and take top features
    effects.sort(reverse=True)
    drivers = [fid for _, fid in effects[:MAX_DRIVERS]]

    # Look for product terms among correlated pairs (|r| >= 0.6)
    products = set()
    correlations = {}

    # Build correlation matrix
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Check for product terms involving top drivers
    for fid1, fid2 in correlations:
        if fid1 in drivers and fid2 in drivers:
            products.add((fid1, fid2))

    # Select columns for regression (drivers + their products)
    columns = list(drivers)
    if products:
        # Add product terms to columns
        for prod in products:
            columns.extend(prod)

    # Limit total terms to prevent overfitting
    if len(columns) > 12:
        # Keep only drivers and minimal products
        columns = drivers[:]
        if products and len(columns) < 12:
            # Add one product pair if space allows
            prod_list = list(products)
            if prod_list:
                columns.extend(prod_list[0])

    # Compute loadings for weighted score using effect sizes
    loadings = {}
    for fid in drivers:
        idx = feats.column(fid)
        # Use effect size as loading weight
        mean_y0 = feats.x[feats.y == 0, idx].mean()
        mean_y1 = feats.x[feats.y == 1, idx].mean()
        loadings[fid] = abs(mean_y1 - mean_y0)

    # Ensure we don't exceed max drivers
    if len(drivers) > 4:
        drivers = drivers[:4]

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

